const prompt = require("prompt-sync")()

const name = prompt(" What is your name? ")
const pizzaFlavor = prompt(" Whatis the desired flavor? ")
const pizzaSize = prompt(" Whatis the desired size? ")

console.log(`
    Here is your detailed order:

    Customer Name: ${name}
    Pizza Flavor: ${pizzaFlavor}
    Pizza Size: ${pizzaSize}

    `)

    let response = prompt(" Y/N ")

console.log(` Is your order correct? ${response}`)

if (response === "Y") {
    console.log(" Your order is being prepared ")
} else if (response === "N") {
    console.log(" Sorry, could you place the order again? ")
}